insert into public.productos (slug, linea, nombre, nombre_base, tamano, categoria_id, precio, descripcion, beneficios, modo_uso, seguridad, cotizar, insignias, tinte, notas, orden) values ('desinfectante-galon', 'desinfectante', 'Desinfectante Multiusos Galón', 'Desinfectante Multiusos', 'Galón', 'hogar', 95.00, 'Mantén tus espacios limpios y libres de gérmenes con nuestro Limpiador Desinfectante. Ideal para pisos y superficies diversas.', array['Elimina el 99.9% de bacterias y gérmenes.', 'Limpieza profunda en diversas superficies.', 'Fórmula efectiva: no deja residuos, garantizando limpieza total.', 'Ideal para uso en hogares, oficinas e instituciones.']::text[], array['Aplica el producto directo o diluido en agua, según la etiqueta.', 'Limpia la superficie con un paño, esponja o trapeador.', 'Deja actuar unos minutos y enjuaga si es necesario.']::text[], false, false, array['mas']::text[], 'lavanda', '{"pino":"Aroma refrescante: el perfume de pino proporciona una sensación de limpieza y frescura.","manzanaverde":"Aroma refrescante: el perfume de manzana verde proporciona una sensación fresca y revitalizante."}'::jsonb, 0);
