insert into public.productos (slug, linea, nombre, nombre_base, tamano, categoria_id, precio, descripcion, beneficios, modo_uso, seguridad, cotizar, insignias, tinte, notas, orden) values ('desengrasante-galon', 'desengrasante', 'Desengrasante Multiusos pH Neutro Galón', 'Desengrasante Multiusos pH Neutro', 'Galón', 'hogar', 120.00, 'Nuestro Desengrasante Multiusos pH Neutro está diseñado para una limpieza efectiva y segura en cualquier tipo de superficie. Su fórmula balanceada elimina grasa, aceite y suciedad sin dañar materiales delicados ni afectar la piel.', array['Elimina grasa, aceite y suciedad.', 'No daña materiales delicados ni afecta la piel.', 'Ideal para uso doméstico, comercial e industrial.']::text[], array['Aplica el producto directo o diluido en agua, según la etiqueta.', 'Limpia la superficie con un paño, esponja o trapeador.', 'Deja actuar unos minutos y enjuaga si es necesario.']::text[], false, false, array['nuevo']::text[], 'manzanaverde', '{}'::jsonb, 2);
