insert into public.productos (slug, linea, nombre, nombre_base, tamano, categoria_id, precio, descripcion, beneficios, modo_uso, seguridad, cotizar, insignias, tinte, notas, orden) values ('biowash', 'biowash', 'Detergente Líquido BIOWASH Galón', 'Detergente Líquido BIOWASH', 'Galón', 'lavanderia', 185.00, 'Detergente líquido de alto rendimiento formulado para limpiar profundamente las prendas, eliminando suciedad y malos olores mientras cuida las fibras y los colores. Su fórmula genera una limpieza eficiente, dejando la ropa fresca, suave y con una agradable fragancia duradera.', array['Limpia profundamente las prendas.', 'Elimina suciedad y malos olores.', 'Cuida las fibras y los colores.', 'Fragancia agradable y duradera.']::text[], array['Agrega la dosis indicada en la etiqueta según el tamaño de la carga.', 'Para manchas difíciles, aplica directo y deja actuar antes de lavar.']::text[], false, false, array['mas']::text[], 'espuma', '{}'::jsonb, 9);
