insert into public.productos (slug, linea, nombre, nombre_base, tamano, categoria_id, precio, descripcion, beneficios, modo_uso, seguridad, cotizar, insignias, tinte, notas, orden) values ('biosoap', 'biosoap', 'BIOSOAP Jabón de Manos Galón', 'BIOSOAP Jabón de Manos', 'Galón', 'alimenticio', 160.00, 'BIOSOAP & BIODISH son jabones líquidos de alta calidad diseñados para brindar una limpieza eficaz y confiable. Formulados con agentes limpiadores y espumantes de alto desempeño, ayudan a remover suciedad, grasa y residuos de manera eficiente. BIOSOAP proporciona una limpieza suave y efectiva para las manos.', array['Limpieza suave y efectiva para las manos.', 'Agentes limpiadores y espumantes de alto desempeño.']::text[], array['Aplica una pequeña cantidad en la esponja o en las manos húmedas.', 'Frota hasta formar espuma y enjuaga con abundante agua.']::text[], false, false, array['nuevo']::text[], 'fresh', '{}'::jsonb, 15);
