insert into public.productos (slug, linea, nombre, nombre_base, tamano, categoria_id, precio, descripcion, beneficios, modo_uso, seguridad, cotizar, insignias, tinte, notas, orden) values ('biofoam-galon', 'biofoam', 'Shampoo de Espuma Activa BIOFOAM X Galón', 'Shampoo de Espuma Activa BIOFOAM X', 'Galón', 'auto', 260.00, 'BIOFOAM X es un shampoo de espuma activa de alto rendimiento, formulado especialmente para hidrolavadoras, cañón de espuma y túneles de carwash. Su tecnología espumante genera una espuma abundante, estable y de gran cobertura, ayudando a remover suciedad mientras mejora la experiencia visual del lavado.', array['Para hidrolavadora, cañón de espuma y carwash.', 'Espuma abundante, estable y de gran cobertura.']::text[], array['Diluye según la etiqueta o aplica directo en presentaciones listas para usar.', 'Aplica sobre la superficie, deja actuar y enjuaga o retira con microfibra.']::text[], false, false, array['nuevo']::text[], 'cereza', '{}'::jsonb, 19);
